exports.main = async () => {
  try { await db.createCollection('themelife') } catch (e) { /* 已存在则忽略 */ }
  const ref = db.collection('themelife').doc('agg')
  const cur = await ref.get()
  const agg = (cur.data && cur.data[0]) || null
  if (agg && agg.last && agg.last >= SEED.last) {
    return { ok: true, skipped: 'baseline-exists', last: agg.last, themes: Object.keys(agg.themes || {}).length }
  }
  const payload = Object.assign({}, SEED, { updated_at: Date.now() })
  await ref.set(payload)
  return { ok: true, seeded: SEED.last, themes: Object.keys(SEED.themes).length }
}
